insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('r-noncredit-title-list-go-sam-2026-11-22','decision','The noncredit subject title list stands on Sam''s word, his to change','Sam, 2026-11-22, in session (S701), on the draft noncredit subject title list: "Looks good. Based on a quick check on my phone. Can we go with it and I can look more closely tomorrow and reverse or change anything that looks wrong?" The 114 titles stand, the noncredit hold lifts (#3667), and he may revise any title after a closer look.',array['commons','subjects','noncredit'],'verified','Sam in session, 2026-11-22; cpl-project-tracker#3667','Sam',now(),'SkyMurre (S701)','2026-11-22'),
('f-coci-credit-status-three-values-sam-2026-11-22','fact','COCI''s credit status indicator has three values: credit, noncredit, noncredit enhanced','Sam, 2026-11-22, in session (S701): "Coci has a credit, noncredit, noncredit enhanced indicator". The Subjects page counts noncredit (N) and noncredit enhanced (E) courses apart on a noncredit row, and the course panel lists the three apart (#3667).',array['commons','subjects','noncredit','coci'],'verified','Sam in session, 2026-11-22; cpl-project-tracker#3667','Sam',now(),'SkyMurre (S701)','2026-11-22')
on conflict (slug) do nothing;

insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('r-subjects-edit-counts-full-width-sam-2026-11-22','decision','Subjects: edit from every surface, clickable counts, full width','Sam, 2026-11-22 ~09:50Z (S701): "need to be able to take action easily when signed in from all subject surfaces"; at ~09:55Z "cobi header has a sign in control so the page doesn''t need it"; counts "should be clickable" with a sidebar of courses; "the subjects surfaces should use the full width of window, which is a design standard". Next session''s first Subjects work.',array['commons','subjects','ui'],'verified','Sam in session, 2026-11-22; docs/session_702_handoff.md','Sam',now(),'SkyMurre (S701)','2026-11-22'),
('d-noncredit-four-categories-no-code-s701','decision','Five noncredit categories keep no common code and show by name','S701: Citizenship, Health and Safety, Home Economics, substantial disabilities and Workforce Preparation keep no common code (the builder lists five; the session first said four); a row under one shows the category by name and takes a local title only. Sky''s call after Sam stood the noncredit title list (r-noncredit-title-list-go-sam-2026-11-22); his to revise.',array['commons','subjects','noncredit'],'proposed','cpl-project-tracker#3667; kb/status/noncredit_subject_titles.json',null,null,'SkyMurre (S701)','2026-11-22'),
('f-subject-save-live-s701','fact','Edit and Save is live on the Subjects page; Sam''s 30 Cerritos decisions are filed','S701 (#3666): a signed-in reviewer saves one kb_curation row, field subject_decision, course_id SUBJ:<college>|<code>|<band>, under the reviewer''s own email. Applied 2026-11-22T04:45Z: 0 SUBJ rows before, 30 inserted under cohort subjects-s701@bot (29 credit, AP whole, ATH as KINE), md5 equal to the committed file''s. Receipt and rollback in kb/migrations.',array['commons','subjects','kb_curation','write-path'],'proposed','cpl-project-tracker#3666; kb/migrations/2026-11-22_s701_subject_decisions_receipt.json',null,null,'SkyMurre (S701)','2026-11-22'),
('p-delete-policy-wider-than-page-s701','pitfall','A table''s DELETE policy can be wider than the page''s Take it back','S701 (#3666): kb_curation''s live DELETE policy lets any allowed reviewer delete any row. The first Take it back deleted by key alone and would have removed another reviewer''s save or a bot-filed one; a second reader caught it. The page deletes by key and the signed-in email and shows the control on the reviewer''s own save only.',array['commons','subjects','kb_curation','pitfall'],'proposed','docs/kb-notes/methodology-a-page-promise-narrower-than-its-delete-policy.md; cpl-project-tracker#3666',null,null,'SkyMurre (S701)','2026-11-22'),
('f-noncredit-hold-lifted-measured-s701','fact','Noncredit hold lifted; four title conditions measured, two used','S701 (#3667), on 99 noncredit-only codes with a heading, right and wrong: same code in a program 13 and 0; the code''s letters run through one title 18 and 13; letters, several titles 9 and 23; courses match 1 and 22. The last two feed no recommendation (wrong more often than right). The 54 held rows became ordinary rows; 4 keep a title recommendation.',array['commons','subjects','noncredit','recommendations'],'proposed','cpl-project-tracker#3667; kb/status/local_subject_recommendations.json noncredit',null,null,'SkyMurre (S701)','2026-11-22'),
('f-credit-catalogs-santa-ana-mtsac-s701','fact','Santa Ana''s and Mt. San Antonio''s credit catalogs are filed','S701 (#3669), kb/_file_credit_catalogs.py: Santa Ana 1,642 credit courses, 94 headings (COCI match 1,597, catalog only 45, COCI only 357); Mt. San Antonio 1,670, 136 (1,584, 86, 220). Not read yet 96 and 136 to 0. Page: courses 18,966 to 22,278, titled 1,412 to 1,636, Not read yet 388 to 156. Mt. SAC prints DN-T and R-TV where COCI writes DN T and R TV.',array['commons','subjects','catalogs','collection'],'proposed','cpl-project-tracker#3669; kb/_file_credit_catalogs.py',null,null,'SkyMurre (S701)','2026-11-22'),
('f-builders-read-subject-decisions-s701','fact','The daily build reads saved subject decisions','S701 (#3670): kb/_sync_subject_decisions.py (anon, reviewer_label only, Range-paged, no email) writes kb/status/subject_decisions.json; kb/subject_decisions.py holds one order: a college''s save, a statewide _SUBJ_DISC:: filing, the subject map, a recommendation. The titles, recommendations, held-codes and pile mint dry-run builders apply it. Codes with a common code 888 to 918.',array['commons','subjects','daily-build','kb_curation'],'proposed','cpl-project-tracker#3670; kb/subject_decisions.py',null,null,'SkyMurre (S701)','2026-11-22'),
('p-decision-never-routes-shell-title-s701','pitfall','A person''s subject decision never routes a shell title into a mint','S701 (#3670): route p placed work experience, practicum and internship titles under the decided code past the 98% floor; at Cerritos 0 of 5 matched (all five sit under WEXP M1001). A second reader caught it. Shell titles stay held whatever a code''s decision says, and the mint plan equals main''s.',array['commons','subjects','pile-mint','pitfall'],'proposed','cpl-project-tracker#3670; person_decision_recall in the pile mint plan',null,null,'SkyMurre (S701)','2026-11-22'),
('f-cerritos-mids-differ-from-decisions-s701','fact','192 Cerritos courses hold an M-ID under a Common SUBJ other than Sam''s decision','S701 (#3670): on ordinary titles the decided code matches the existing M-ID''s SUBJ4 for 253 of 440 Cerritos courses; 192 courses hold an M-ID under another Common SUBJ (ATH''s 84 under ATHL against KINE). Aligning them is a re-mint under docs/coursecontrolnumber_remint.md; not done, and nothing is re-minted without a reply.',array['commons','subjects','cerritos','m-id','re-mint'],'proposed','cpl-project-tracker#3670',null,null,'SkyMurre (S701)','2026-11-22'),
('p-shared-branch-name-stale-checkout-s701','pitfall','A worker''s worktree and the main checkout on one branch name leave the checkout stale','S701: a worker''s worktree and the main checkout on the same branch name left the main checkout''s files behind the branch and fired the stop hook. Workers take a local branch of another name and push to the session branch. The stale files went to stash s701-stale-main-checkout-0552, which holds nothing else.',array['conductor','worktree','git','pitfall'],'proposed','S701 session; docs/session_702_handoff.md',null,null,'SkyMurre (S701)','2026-11-22')
on conflict (slug) do nothing;

